<script lang="ts">import {canonical} from '#lib/seo';export let data;const url=canonical(data.site,data.article.slug);const schema=JSON.stringify({'@context':'https://schema.org','@type':'BlogPosting',headline:data.article.title,description:data.article.meta_description,datePublished:data.article.published_at,mainEntityOfPage:url,publisher:{'@type':'Organization',name:data.site.name}}).replace(/</g,'\\u003c');</script>
<svelte:head><title>{data.article.title} | {data.site.name}</title><meta name="description" content={data.article.meta_description} /><link rel="canonical" href={url} /><meta property="og:type" content="article" /><meta property="og:title" content={data.article.title} /><meta property="og:description" content={data.article.meta_description} /><meta property="og:url" content={url} /><script type="application/ld+json">{@html schema}</script></svelte:head>
<main><article class="article-body"><p class="eyebrow"><a href={data.site.blog_prefix}>← Blog de {data.site.name}</a></p><h1>{data.article.title}</h1><p class="muted">Publicado el {new Date(data.article.published_at).toLocaleDateString('es-MX')}</p><p class="lead">{data.article.summary}</p><p>{data.article.content.intro}</p>{#each data.article.content.sections as section}<section><h2>{section.heading}</h2>{#each section.paragraphs as paragraph}<p>{paragraph}</p>{/each}{#if section.bullets.length}<ul>{#each section.bullets as bullet}<li>{bullet}</li>{/each}</ul>{/if}</section>{/each}{#if data.article.content.faq.length}<section><h2>Preguntas frecuentes</h2>{#each data.article.content.faq as item}<h3>{item.question}</h3><p>{item.answer}</p>{/each}</section>{/if}</article></main>
